import { useContext } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { ThemeContext } from "@dash/Context/ThemeContext";
import { getStylesForItem, getUUID } from "@dash/Utils";
import { themeObjects } from "@dash/Utils/themeObjects";

// Icon-only buttons need an accessible name (WCAG 4.1.2). Callers should pass
// `ariaLabel`; without one, the icon's name stands in ("xmark" → "Close").
// A toggle (a rail or toolbar button that shows a panel) passes `ariaPressed`;
// `selected` also marks the button `data-selected` so the Aurora treatment can
// show it in both modes (design guide, rule 13).
const ICON_NAMES = {
    xmark: "Close",
    times: "Close",
    plus: "Add",
    trash: "Delete",
    "trash-can": "Delete",
    pen: "Edit",
    pencil: "Edit",
    "pen-to-square": "Edit",
    gear: "Settings",
    cog: "Settings",
    "magnifying-glass": "Search",
    search: "Search",
    "arrow-left": "Back",
    "chevron-left": "Back",
    ellipsis: "More",
    "ellipsis-vertical": "More",
    "rotate-right": "Refresh",
    rotate: "Refresh",
    copy: "Copy",
    check: "Done",
};
export function iconLabel(icon) {
    const name = Array.isArray(icon)
        ? icon[1]
        : typeof icon === "string"
          ? icon
          : icon && icon.iconName;
    if (!name) return undefined;
    const key = String(name).replace(/^fa-/, "");
    if (ICON_NAMES[key]) return ICON_NAMES[key];
    const words = key.replace(/-/g, " ");
    return words.charAt(0).toUpperCase() + words.slice(1);
}

const ButtonIcon = ({
    onClick = null,
    icon = "",
    text = "",
    block = false,
    textSize = null,
    textColor = "",
    iconSize = null,
    backgroundColor = null,
    selected = false,
    selectedBackgroundColor = null,
    selectedTextColor = null,
    disabled = false,
    className = "",
    size = "md",
    ariaLabel = null,
    ariaPressed = null,
    testId = undefined,
    children,
    ...props
}) => {
    const { currentTheme } = useContext(ThemeContext);
    const styles = getStylesForItem(
        themeObjects.BUTTON_ICON,
        currentTheme,
        {
            ...props,
            backgroundColor,
            textColor,
            selectedBackgroundColor,
            selectedTextColor,
            scrollable: false,
            grow: false,
        },
        null,
        size
    );

    const uuid = getUUID("", "button-icon");
    const computedIconSize = iconSize || styles.iconSize || "h-5 w-5";
    const hasIcon = icon !== "";
    // Accept the button label via `text` prop (canonical) OR children
    // (LLM-friendly shorthand). Prop wins when both are provided.
    const effectiveText = text !== "" && text !== null ? text : children;
    const hasText =
        effectiveText !== undefined &&
        effectiveText !== null &&
        effectiveText !== "";

    const bgColor = selected
        ? styles.selectedBackgroundColor || styles.backgroundColor || ""
        : styles.backgroundColor || "";
    const txtColor = selected
        ? styles.selectedTextColor || styles.textColor || ""
        : styles.textColor || "";

    return (
        <button
            type="button"
            id={uuid}
            onClick={onClick}
            disabled={disabled}
            aria-label={ariaLabel || (hasText ? undefined : iconLabel(icon))}
            data-testid={testId}
            aria-pressed={ariaPressed === null ? undefined : !!ariaPressed}
            data-selected={selected ? "true" : undefined}
            className={`dr-btn-icon inline-flex items-center justify-center ${hasIcon && hasText ? "gap-2" : ""} ${block ? "w-full" : ""} ${bgColor} ${txtColor} ${styles.borderColor || ""} ${styles.hoverBackgroundColor || ""} ${styles.hoverTextColor || ""} ${styles.hoverBorderColor || ""} ${styles.borderRadius || "rounded-md"} ${styles.spacing || "px-3 py-2"} ${styles.textSize || "text-base"} ${styles.shadow || ""} ${styles.transition || "transition-colors duration-150"} ${styles.fontWeight || ""} ${styles.cursor || "cursor-pointer"} ${styles.disabledOpacity || ""} focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 ${styles.focusRingColor || ""} whitespace-nowrap ${className}`}
        >
            {hasIcon && (
                <FontAwesomeIcon icon={icon} className={computedIconSize} />
            )}
            {hasText && <span>{effectiveText}</span>}
        </button>
    );
};

